import itertools
from reduce import reduce

def sat_solve(inst):
    m = inst["num_vars"]; clauses = inst["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        if all(any((bits[abs(l)-1] if l > 0 else not bits[abs(l)-1]) for l in cl) for cl in clauses):
            return True
    return False

def color_solve(inst):
    n = inst["n"]
    adj = [set() for _ in range(n)]
    for u, v in inst["edges"]:
        adj[u].add(v); adj[v].add(u)
    colors = [-1]*n
    def bt():
        best = -1; best_avail = None
        for i in range(n):
            if colors[i] == -1:
                avail = [c for c in range(3) if all(colors[j] != c for j in adj[i])]
                if best == -1 or len(avail) < len(best_avail):
                    best = i; best_avail = avail
                    if len(avail) == 0:
                        return False
        if best == -1:
            return True
        for c in best_avail:
            colors[best] = c
            if bt():
                return True
            colors[best] = -1
        return False
    return bt()

# Suspected counterexample: every satisfying assignment has an all-true clause
inst = {"num_vars": 3, "clauses": [[1,2,3],[1,2,-3],[1,-2,3],[-1,2,3]]}
print("sat:", sat_solve(inst))
g = reduce(inst)
print("graph n:", g["n"], "edges:", g["edges"])
print("3-colorable:", color_solve(g))
EOF
